import{_ as r,o as a,c as o,a6 as n}from"./chunks/framework.BrkgobfX.js";const d=JSON.parse('{"title":"HTTP/2 与 HTTP/3 协议详解","description":"二进制分帧、HPACK/QPACK、多路复用与 QUIC——逐项拆解 HTTP/2 与 HTTP/3 相对 1.1 改了什么。","frontmatter":{"title":"HTTP/2 与 HTTP/3 协议详解","description":"二进制分帧、HPACK/QPACK、多路复用与 QUIC——逐项拆解 HTTP/2 与 HTTP/3 相对 1.1 改了什么。","source":"https://daiw.org/manual/http2-3"},"headers":[],"relativePath":"manual/computer-programming/http2-3/index.md","filePath":"manual/computer-programming/http2-3/index.md"}'),l={name:"manual/computer-programming/http2-3/index.md"};function e(h,t,m,p,i,u){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="http-2-与-http-3-协议详解" tabindex="-1">HTTP/2 与 HTTP/3 协议详解 <a class="header-anchor" href="#http-2-与-http-3-协议详解" aria-label="Permalink to &quot;HTTP/2 与 HTTP/3 协议详解&quot;">​</a></h1><blockquote><p>内容来源：<a href="https://daiw.org/manual/http2-3" target="_blank" rel="noreferrer">daiw.org</a> · 作者 David · 原文更新于 2026-08-03</p></blockquote><p>二进制分帧、HPACK/QPACK、多路复用与 QUIC——逐项拆解 HTTP/2 与 HTTP/3 相对 1.1 改了什么。</p><p>本专栏只回答一个问题：<strong>HTTP/2 与 HTTP/3 相对 HTTP/1.1 具体改了什么，怎么改的，代价是什么。</strong></p><p>前提：<a href="/Front2Full/manual/computer-programming/http11/">《HTTP/1.1 协议详解》</a>。本专栏默认你已知道 1.1 的报文语法与字段语义，不再重复。</p><h2 id="一句话概括" tabindex="-1">一句话概括 <a class="header-anchor" href="#一句话概括" aria-label="Permalink to &quot;一句话概括&quot;">​</a></h2><ul><li><strong>HTTP/2</strong> 换掉了 1.1 的<strong>报文成帧层</strong>——文本行改二进制帧，一条连接上多路复用多个请求，头部用 HPACK 压缩。<strong>语义完全不变</strong>。</li><li><strong>HTTP/3</strong> 换掉了 HTTP/2 的<strong>传输层</strong>——TCP 改 QUIC（跑在 UDP 上），消除 TCP 层的队头阻塞，握手从 2–3 RTT 降到 1 RTT（复访 0 RTT）。</li></ul><p><strong>三个版本的语义是同一套</strong>：方法、状态码、字段含义、条件请求、缓存、认证全部沿用 RFC 9110。变的只有「字节怎么排」与「跑在什么之上」。</p><h2 id="规范基准" tabindex="-1">规范基准 <a class="header-anchor" href="#规范基准" aria-label="Permalink to &quot;规范基准&quot;">​</a></h2><table tabindex="0"><thead><tr><th>规范</th><th>RFC</th><th>年份</th></tr></thead><tbody><tr><td>HTTP 语义（三版共用）</td><td>9110</td><td>2022</td></tr><tr><td>HTTP/2</td><td><strong>9113</strong>（废止 7540）</td><td>2022</td></tr><tr><td>HPACK（h2 头压缩）</td><td>7541</td><td>2015</td></tr><tr><td>HTTP/3</td><td><strong>9114</strong></td><td>2022</td></tr><tr><td>QPACK（h3 头压缩）</td><td>9204</td><td>2022</td></tr><tr><td>QUIC 传输 / TLS / 恢复</td><td>9000 / 9001 / 9002</td><td>2021</td></tr><tr><td>可扩展优先级</td><td>9218</td><td>2022</td></tr></tbody></table><h2 id="_1-1-的四个瓶颈" tabindex="-1">1.1 的四个瓶颈 <a class="header-anchor" href="#_1-1-的四个瓶颈" aria-label="Permalink to &quot;1.1 的四个瓶颈&quot;">​</a></h2><p>后面每一章都在解决其中之一：</p><table tabindex="0"><thead><tr><th>瓶颈</th><th>1.1 的表现</th><th>解法</th></tr></thead><tbody><tr><td><strong>队头阻塞（应用层）</strong></td><td>流水线中一个慢响应堵住其后全部</td><td>h2 <a href="/Front2Full/manual/computer-programming/http2-3/h2-streams">多路复用</a></td></tr><tr><td><strong>队头阻塞（传输层）</strong></td><td>一个 TCP 包丢失，其后所有数据等重传</td><td>h3 <a href="/Front2Full/manual/computer-programming/http2-3/quic-transport">QUIC 流</a></td></tr><tr><td><strong>头部冗余</strong></td><td>每请求重发全部字段，明文数百字节</td><td>h2 <a href="/Front2Full/manual/computer-programming/http2-3/hpack">HPACK</a> / h3 <a href="/Front2Full/manual/computer-programming/http2-3/qpack">QPACK</a></td></tr><tr><td><strong>连接数爆炸</strong></td><td>浏览器每域开 6 条连接绕开阻塞</td><td>单连接多路复用</td></tr></tbody></table><h2 id="阅读顺序" tabindex="-1">阅读顺序 <a class="header-anchor" href="#阅读顺序" aria-label="Permalink to &quot;阅读顺序&quot;">​</a></h2><p><strong>第 1 部分 · HTTP/2</strong>——<a href="/Front2Full/manual/computer-programming/http2-3/h2-overview">总览</a>、<a href="/Front2Full/manual/computer-programming/http2-3/h2-framing">二进制分帧</a>、<a href="/Front2Full/manual/computer-programming/http2-3/h2-streams">流与多路复用</a>、<a href="/Front2Full/manual/computer-programming/http2-3/hpack">HPACK</a>、<a href="/Front2Full/manual/computer-programming/http2-3/h2-pseudo-headers">伪头字段</a>、<a href="/Front2Full/manual/computer-programming/http2-3/h2-flow-control">流量控制</a>、<a href="/Front2Full/manual/computer-programming/http2-3/h2-settings-priority">SETTINGS 与优先级</a>、<a href="/Front2Full/manual/computer-programming/http2-3/h2-connection">连接管理</a>、<a href="/Front2Full/manual/computer-programming/http2-3/h2-server-push">服务端推送</a>。</p><p><strong>第 2 部分 · HTTP/3 与 QUIC</strong>——<a href="/Front2Full/manual/computer-programming/http2-3/h3-overview">总览</a>、<a href="/Front2Full/manual/computer-programming/http2-3/quic-transport">QUIC 传输层</a>、<a href="/Front2Full/manual/computer-programming/http2-3/h3-framing">帧格式</a>、<a href="/Front2Full/manual/computer-programming/http2-3/qpack">QPACK</a>、<a href="/Front2Full/manual/computer-programming/http2-3/h3-connection">连接与发现</a>。</p><p><strong>第 3 部分 · 对照与迁移</strong>——<a href="/Front2Full/manual/computer-programming/http2-3/version-comparison">三版全面对照</a>、<a href="/Front2Full/manual/computer-programming/http2-3/migration-notes">迁移注意事项</a>。</p><p>从 <a href="/Front2Full/manual/computer-programming/http2-3/h2-overview">HTTP/2 总览</a> 开始。</p><h2 id="本专栏篇目" tabindex="-1">本专栏篇目 <a class="header-anchor" href="#本专栏篇目" aria-label="Permalink to &quot;本专栏篇目&quot;">​</a></h2><ul><li><a href="/Front2Full/manual/computer-programming/http2-3/">HTTP/2 与 HTTP/3 协议详解</a>: 二进制分帧、HPACK/QPACK、多路复用与 QUIC——逐项拆解 HTTP/2 与 HTTP/3 相对 1.1 改了什么。</li></ul><h3 id="第-1-部分-·-http-2" tabindex="-1">第 1 部分 · HTTP/2 <a class="header-anchor" href="#第-1-部分-·-http-2" aria-label="Permalink to &quot;第 1 部分 · HTTP/2&quot;">​</a></h3><ul><li><a href="/Front2Full/manual/computer-programming/http2-3/h2-overview">HTTP/2 总览</a>: h2 改了什么、没改什么，以及 ALPN 协商与 h2c 的废弃。</li><li><a href="/Front2Full/manual/computer-programming/http2-3/h2-framing">二进制分帧层</a>: 9 字节帧头的每个比特、十种帧类型与标志位的精确语义。</li><li><a href="/Front2Full/manual/computer-programming/http2-3/h2-streams">流与多路复用</a>: 流 ID 分配规则、七态状态机与多路复用如何消除应用层队头阻塞。</li><li><a href="/Front2Full/manual/computer-programming/http2-3/hpack">HPACK 头部压缩</a>: 静态表、动态表、整数与字符串编码、六种字段表示格式，以及为何不用 gzip。</li><li><a href="/Front2Full/manual/computer-programming/http2-3/h2-pseudo-headers">伪头字段</a>: 五个冒号开头的伪头、与 1.1 起始行的映射，以及被禁用的连接级字段。</li><li><a href="/Front2Full/manual/computer-programming/http2-3/h2-flow-control">流量控制</a>: 连接级与流级窗口、WINDOW_UPDATE 语义与初始窗口变更的边界情况。</li><li><a href="/Front2Full/manual/computer-programming/http2-3/h2-settings-priority">SETTINGS 与优先级</a>: 六个 SETTINGS 参数、ACK 机制，以及优先级树的废弃与 RFC 9218 扩展优先级。</li><li><a href="/Front2Full/manual/computer-programming/http2-3/h2-connection">连接管理与错误码</a>: 连接前言、GOAWAY 的优雅关闭语义、十四个错误码与流错误/连接错误的区分。</li><li><a href="/Front2Full/manual/computer-programming/http2-3/h2-server-push">服务端推送</a>: PUSH_PROMISE 机制、它为什么失败，以及 103 Early Hints 这个替代方案。</li></ul><h3 id="第-2-部分-·-http-3-与-quic" tabindex="-1">第 2 部分 · HTTP/3 与 QUIC <a class="header-anchor" href="#第-2-部分-·-http-3-与-quic" aria-label="Permalink to &quot;第 2 部分 · HTTP/3 与 QUIC&quot;">​</a></h3><ul><li><a href="/Front2Full/manual/computer-programming/http2-3/h3-overview">HTTP/3 总览</a>: TCP 队头阻塞为什么无法在 TCP 上解决，以及 h3 = HTTP/2 语义 + QUIC 传输。</li><li><a href="/Front2Full/manual/computer-programming/http2-3/quic-transport">QUIC 传输层</a>: 流与流 ID、变长整数、1-RTT/0-RTT 握手、连接 ID 与连接迁移。</li><li><a href="/Front2Full/manual/computer-programming/http2-3/h3-framing">HTTP/3 帧格式</a>: 变长帧头、七种帧类型、四类单向流，以及被删除的 h2 帧。</li><li><a href="/Front2Full/manual/computer-programming/http2-3/qpack">QPACK 头部压缩</a>: HPACK 为何在乱序交付下失效、编码器/解码器流、Required Insert Count 与阻塞流。</li><li><a href="/Front2Full/manual/computer-programming/http2-3/h3-connection">连接与服务发现</a>: Alt-Svc、DNS HTTPS 记录、GOAWAY 的双向语义与回落策略。</li></ul><h3 id="第-3-部分-·-对照与迁移" tabindex="-1">第 3 部分 · 对照与迁移 <a class="header-anchor" href="#第-3-部分-·-对照与迁移" aria-label="Permalink to &quot;第 3 部分 · 对照与迁移&quot;">​</a></h3><ul><li><a href="/Front2Full/manual/computer-programming/http2-3/version-comparison">三版全面对照</a>: 1.1 / 2 / 3 在成帧、多路复用、压缩、连接管理与安全上的逐项差异表。</li><li><a href="/Front2Full/manual/computer-programming/http2-3/migration-notes">迁移注意事项</a>: 哪些 1.1 知识作废、哪些照旧，以及升级 h2/h3 时真正会踩的坑。</li></ul>',26)])])}const T=r(l,[["render",e]]);export{d as __pageData,T as default};
